from pyspark.sql import functions as F

# The first plan can't broadcast (a 10-byte limit), but adaptive execution may (its limit is 10 MB).
spark.conf.set("spark.sql.adaptive.enabled", True)
spark.conf.set("spark.sql.autoBroadcastJoinThreshold", 10)
spark.conf.set("spark.sql.adaptive.autoBroadcastJoinThreshold", "10MB")


def report(rows, planned_sort_merge, ran_broadcast):
    return spark.createDataFrame(
        [(rows, planned_sort_merge, ran_broadcast)],
        "rows bigint, planned_sort_merge boolean, ran_broadcast boolean",
    )


def solve(shipments, warehouses):
    joined = shipments.join(warehouses, "warehouse_id")
    plan = joined._jdf.queryExecution().executedPlan().toString()
    rows = joined.count()
    return report(rows, "SortMergeJoin" in plan, "BroadcastHashJoin" in plan)
